//! Parsing of human friendly durations ("1h30m", "5s", "250ms") and of
//! RFC3339-like timestamps ("2018-04-20 04:20:00").

use std::fmt;
use std::str::Chars;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DurationError {
    InvalidCharacter(usize),
    NumberExpected(usize),
    UnknownUnit(usize, usize),
    NumberOverflow,
    Empty,
}

impl fmt::Display for DurationError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            DurationError::InvalidCharacter(at) => write!(f, "invalid character at {}", at),
            DurationError::NumberExpected(at) => write!(f, "expected number at {}", at),
            DurationError::UnknownUnit(a, b) => write!(f, "unknown unit at {}-{}", a, b),
            DurationError::NumberOverflow => write!(f, "number is too large"),
            DurationError::Empty => write!(f, "value was empty"),
        }
    }
}

struct DurationParser<'a> {
    chars: Chars<'a>,
    text: &'a str,
    secs: u64,
    nanos: u64,
}

impl<'a> DurationParser<'a> {
    fn position(&self) -> usize {
        self.text.len() - self.chars.as_str().len()
    }

    /// Skips leading whitespace and reads the first digit of a number.
    fn leading_digit(&mut self) -> Result<Option<u64>, DurationError> {
        let at = self.position();
        while let Some(ch) = self.chars.next() {
            if ch.is_ascii_digit() {
                return Ok(Some(ch as u64 - '0' as u64));
            }
            if ch.is_whitespace() {
                continue;
            }
            return Err(DurationError::NumberExpected(at));
        }
        Ok(None)
    }

    fn apply_unit(&mut self, value: u64, from: usize, to: usize) -> Result<(), DurationError> {
        let mul = |v: u64, m: u64| v.checked_mul(m).ok_or(DurationError::NumberOverflow);
        let (mut secs, nanos) = match &self.text[from..to] {
            "nanos" | "nsec" | "ns" => (0u64, value),
            "usec" | "us" => (0u64, mul(value, 1_000)?),
            "millis" | "msec" | "ms" => (0u64, mul(value, 1_000_000)?),
            "seconds" | "second" | "secs" | "sec" | "s" => (value, 0u64),
            "minutes" | "minute" | "min" | "mins" | "m" => (mul(value, 60)?, 0),
            "hours" | "hour" | "hr" | "hrs" | "h" => (mul(value, 3_600)?, 0),
            "days" | "day" | "d" => (mul(value, 86_400)?, 0),
            "weeks" | "week" | "w" => (mul(value, 604_800)?, 0),
            "months" | "month" | "M" => (mul(value, 2_630_016)?, 0),
            "years" | "year" | "y" => (mul(value, 31_557_600)?, 0),
            _ => return Err(DurationError::UnknownUnit(from, to)),
        };
        let mut nanos = self.nanos.wrapping_add(nanos);
        if nanos > 1_000_000_000 {
            secs = secs.wrapping_add(nanos / 1_000_000_000);
            nanos %= 1_000_000_000;
        }
        self.secs = self.secs.checked_add(secs).ok_or(DurationError::NumberOverflow)?;
        self.nanos = nanos;
        Ok(())
    }

    fn run(mut self) -> Result<Duration, DurationError> {
        let mut value = match self.leading_digit()? {
            Some(d) => d,
            None => return Err(DurationError::Empty),
        };
        'number: loop {
            // Accumulate the digits of the number (whitespace is ignored).
            let mut at = self.position();
            while let Some(ch) = self.chars.next() {
                if ch.is_ascii_digit() {
                    value = value
                        .checked_mul(10)
                        .and_then(|v| v.checked_add(ch as u64 - '0' as u64))
                        .ok_or(DurationError::NumberOverflow)?;
                } else if ch.is_whitespace() {
                } else if ch.is_ascii_alphabetic() {
                    break;
                } else {
                    return Err(DurationError::InvalidCharacter(at));
                }
                at = self.position();
            }
            // Now read the unit.
            let unit_start = at;
            let mut at = self.position();
            while let Some(ch) = self.chars.next() {
                if ch.is_ascii_digit() {
                    self.apply_unit(value, unit_start, at)?;
                    value = ch as u64 - '0' as u64;
                    continue 'number;
                } else if ch.is_whitespace() {
                    break;
                } else if ch.is_ascii_alphabetic() {
                } else {
                    return Err(DurationError::InvalidCharacter(at));
                }
                at = self.position();
            }
            self.apply_unit(value, unit_start, at)?;
            value = match self.leading_digit()? {
                Some(d) => d,
                None => return Ok(Duration::new(self.secs, self.nanos as u32)),
            };
        }
    }
}

pub fn parse_duration(text: &str) -> Result<Duration, DurationError> {
    DurationParser { chars: text.chars(), text, secs: 0, nanos: 0 }.run()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TimestampError {
    OutOfRange,
    InvalidDigit,
    InvalidFormat,
}

impl fmt::Display for TimestampError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            TimestampError::OutOfRange => write!(f, "numeric component is out of range"),
            TimestampError::InvalidDigit => write!(f, "bad character where digit is expected"),
            TimestampError::InvalidFormat => write!(f, "timestamp format is invalid"),
        }
    }
}

fn pair(hi: u8, lo: u8) -> Result<u64, TimestampError> {
    if !hi.is_ascii_digit() || !lo.is_ascii_digit() {
        return Err(TimestampError::InvalidDigit);
    }
    Ok(((hi - b'0') as u64) * 10 + (lo - b'0') as u64)
}

fn is_leap(year: u64) -> bool {
    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
}

/// Parses "YYYY-MM-DD hh:mm:ss[.frac][Z]" (a 'T' separator is accepted too),
/// interpreted as UTC.
pub fn parse_timestamp(text: &str) -> Result<SystemTime, TimestampError> {
    let b = text.as_bytes();
    if b.len() < 19 {
        return Err(TimestampError::InvalidFormat);
    }
    if b[4] != b'-' || b[7] != b'-' || (b[10] != b'T' && b[10] != b' ') || b[13] != b':' || b[16] != b':' {
        return Err(TimestampError::InvalidFormat);
    }
    let year = pair(b[0], b[1])? * 100 + pair(b[2], b[3])?;
    let month = pair(b[5], b[6])?;
    let day = pair(b[8], b[9])?;
    let hour = pair(b[11], b[12])?;
    let minute = pair(b[14], b[15])?;
    let mut second = pair(b[17], b[18])?;

    if year < 1970 || hour > 23 || minute > 59 || second > 60 {
        return Err(TimestampError::OutOfRange);
    }
    if second == 60 {
        second = 59;
    }
    let leap = is_leap(year);
    let (mut yday, month_len) = match month {
        1 => (0, 31),
        2 => (31, if leap { 29 } else { 28 }),
        3 => (59, 31),
        4 => (90, 30),
        5 => (120, 31),
        6 => (151, 30),
        7 => (181, 31),
        8 => (212, 31),
        9 => (243, 30),
        10 => (273, 31),
        11 => (304, 30),
        12 => (334, 31),
        _ => return Err(TimestampError::OutOfRange),
    };
    if day == 0 || day > month_len {
        return Err(TimestampError::OutOfRange);
    }
    yday += day - 1;
    if leap && month > 2 {
        yday += 1;
    }
    let prev = year - 1;
    let leap_days = (prev - 1968) / 4 - (prev - 1900) / 100 + (prev - 1600) / 400;
    let days = (year - 1970) * 365 + leap_days + yday;
    let day_secs = second + minute * 60 + hour * 3600;

    let mut nanos: u32 = 0;
    let mut scale: u32 = 100_000_000;
    if b.len() > 19 && b[19] == b'.' {
        for idx in 20..b.len() {
            if b[idx] == b'Z' {
                if idx == b.len() - 1 {
                    break;
                }
                return Err(TimestampError::InvalidDigit);
            }
            if !b[idx].is_ascii_digit() {
                return Err(TimestampError::InvalidDigit);
            }
            nanos += scale * (b[idx] - b'0') as u32;
            scale /= 10;
        }
    } else if b.len() != 19 && (b.len() > 20 || b[19] != b'Z') {
        return Err(TimestampError::InvalidFormat);
    }
    let total = day_secs + days * 86_400;
    Ok(UNIX_EPOCH + Duration::new(total, nanos))
}
EOF"}

