//! Regular expression handling for `--until-match`.
//!
//! The matching itself is delegated to the `regex` crate.  The tool being
//! reimplemented was built against an older generation of that engine, which
//! rejected a handful of constructs that are accepted nowadays.  The checks in
//! this module reproduce those rejections (and their diagnostics) so that the
//! observable behaviour stays the same.

use regex::Regex;
use regex_syntax::ast::{self, Ast, ClassSet, ClassSetItem, Position, Span};

const EMPTY_ALTERNATION: &str = "alternations cannot currently contain empty sub-expressions";

/// Compile a pattern, returning the user facing error message on failure.
pub fn compile(pattern: &str) -> Result<Regex, String> {
    let tree = match ast::parse::Parser::new().parse(pattern) {
        Ok(tree) => tree,
        Err(err) => return Err(legacy_parse_error(pattern, &err).unwrap_or_else(|| err.to_string())),
    };

    let mut walker = Walker { pattern, problems: Vec::new(), classes: Vec::new(), empty_alt: false };
    let mut state = FlagState { insensitive: false, unicode: true, verbose: false };
    walker.visit(&tree, &mut state);

    if let Some((span, msg)) = walker.problems.iter().min_by_key(|(span, _)| span.start.offset) {
        return Err(render(pattern, span, msg));
    }

    // Translation stage: classes that turn out to be empty used to be an error.
    let empty_class = walker.classes.iter().find(|(span, st)| class_is_empty(pattern, span, st)).map(|(s, _)| *s);
    let translated = regex_syntax::ParserBuilder::new().build().parse(pattern);
    match (&translated, empty_class) {
        (Err(regex_syntax::Error::Translate(err)), Some(span)) => {
            if span.start.offset < err.span().start.offset {
                return Err(render(pattern, &span, "empty character classes are not allowed"));
            }
            return Err(translated.unwrap_err().to_string());
        }
        (Err(err), _) => return Err(err.to_string()),
        (Ok(_), Some(span)) => return Err(render(pattern, &span, "empty character classes are not allowed")),
        (Ok(_), None) => {}
    }

    if walker.empty_alt {
        return Err(EMPTY_ALTERNATION.to_string());
    }

    Regex::new(pattern).map_err(|e| e.to_string())
}

#[derive(Clone, Copy)]
struct FlagState {
    insensitive: bool,
    unicode: bool,
    verbose: bool,
}

impl FlagState {
    fn apply(&mut self, flags: &ast::Flags) {
        let mut on = true;
        for item in &flags.items {
            match item.kind {
                ast::FlagsItemKind::Negation => on = false,
                ast::FlagsItemKind::Flag(ast::Flag::CaseInsensitive) => self.insensitive = on,
                ast::FlagsItemKind::Flag(ast::Flag::Unicode) => self.unicode = on,
                ast::FlagsItemKind::Flag(ast::Flag::IgnoreWhitespace) => self.verbose = on,
                _ => {}
            }
        }
    }

    fn prefix(&self) -> String {
        let mut s = String::new();
        if self.insensitive {
            s.push('i');
        }
        if self.verbose {
            s.push('x');
        }
        if !self.unicode {
            s.push_str("-u");
        }
        if s.is_empty() {
            s
        } else {
            format!("(?{})", s)
        }
    }
}

struct Walker<'p> {
    pattern: &'p str,
    problems: Vec<(Span, &'static str)>,
    classes: Vec<(Span, FlagState)>,
    empty_alt: bool,
}

fn shifted(pattern: &str, pos: Position, chars: usize) -> Position {
    let mut p = pos;
    for ch in pattern[pos.offset..].chars().take(chars) {
        p.offset += ch.len_utf8();
        p.column += 1;
    }
    p
}

impl<'p> Walker<'p> {
    fn literal(&mut self, lit: &ast::Literal, state: &FlagState) {
        if lit.kind == ast::LiteralKind::Superfluous && !(lit.c == ' ' && state.verbose) {
            self.problems.push((lit.span, "unrecognized escape sequence"));
        }
    }

    fn flags(&mut self, flags: &ast::Flags) {
        for item in &flags.items {
            if item.kind == ast::FlagsItemKind::Flag(ast::Flag::CRLF) {
                self.problems.push((item.span, "unrecognized flag"));
                break;
            }
        }
    }

    fn class_item(&mut self, item: &ClassSetItem, state: &FlagState) {
        match item {
            ClassSetItem::Literal(lit) => self.literal(lit, state),
            ClassSetItem::Range(r) => {
                self.literal(&r.start, state);
                self.literal(&r.end, state);
            }
            ClassSetItem::Bracketed(b) => self.class_set(&b.kind, state),
            ClassSetItem::Union(u) => {
                for it in &u.items {
                    self.class_item(it, state);
                }
            }
            _ => {}
        }
    }

    fn class_set(&mut self, set: &ClassSet, state: &FlagState) {
        match set {
            ClassSet::Item(item) => self.class_item(item, state),
            ClassSet::BinaryOp(op) => {
                self.class_set(&op.lhs, state);
                self.class_set(&op.rhs, state);
            }
        }
    }

    fn visit(&mut self, node: &Ast, state: &mut FlagState) {
        match node {
            Ast::Empty(_) | Ast::Dot(_) | Ast::ClassPerl(_) | Ast::ClassUnicode(_) => {}
            Ast::Flags(set) => {
                self.flags(&set.flags);
                state.apply(&set.flags);
            }
            Ast::Literal(lit) => self.literal(lit, state),
            Ast::Assertion(a) => match a.kind {
                ast::AssertionKind::WordBoundaryStartAngle | ast::AssertionKind::WordBoundaryEndAngle => {
                    self.problems.push((a.span, "unrecognized escape sequence"));
                }
                ast::AssertionKind::WordBoundaryStart
                | ast::AssertionKind::WordBoundaryEnd
                | ast::AssertionKind::WordBoundaryStartHalf
                | ast::AssertionKind::WordBoundaryEndHalf => {
                    let at = shifted(self.pattern, a.span.start, 3);
                    self.problems.push((Span::splat(at), "repetition quantifier expects a valid decimal"));
                }
                _ => {}
            },
            Ast::ClassBracketed(b) => {
                self.class_set(&b.kind, state);
                self.classes.push((b.span, *state));
            }
            Ast::Repetition(rep) => self.visit(&rep.ast, state),
            Ast::Group(g) => {
                let mut inner = *state;
                match &g.kind {
                    ast::GroupKind::CaptureName { starts_with_p, name } => {
                        if !starts_with_p {
                            let at = shifted(self.pattern, g.span.start, 2);
                            self.problems.push((Span::new(at, shifted(self.pattern, at, 1)), "unrecognized flag"));
                        } else if let Some((idx, _)) = name
                            .name
                            .char_indices()
                            .find(|(_, c)| !(c.is_ascii_alphanumeric() || *c == '_'))
                        {
                            let chars = name.name[..idx].chars().count();
                            let at = shifted(self.pattern, name.span.start, chars);
                            self.problems.push((Span::new(at, shifted(self.pattern, at, 1)), "invalid capture group character"));
                        }
                    }
                    ast::GroupKind::NonCapturing(flags) => {
                        self.flags(flags);
                        inner.apply(flags);
                    }
                    ast::GroupKind::CaptureIndex(_) => {}
                }
                self.visit(&g.ast, &mut inner);
            }
            Ast::Alternation(alt) => {
                for branch in &alt.asts {
                    if compiles_to_nothing(branch) {
                        self.empty_alt = true;
                    }
                    self.visit(branch, state);
                }
            }
            Ast::Concat(cat) => {
                for part in &cat.asts {
                    self.visit(part, state);
                }
            }
        }
    }
}

/// Whether the legacy compiler would have emitted no instruction at all for
/// this expression (capture slots are not counted, as they are dropped when
/// building the DFA programs).
fn compiles_to_nothing(node: &Ast) -> bool {
    match node {
        Ast::Empty(_) | Ast::Flags(_) => true,
        Ast::Literal(_) | Ast::Dot(_) | Ast::Assertion(_) => false,
        Ast::ClassUnicode(_) | Ast::ClassPerl(_) | Ast::ClassBracketed(_) => false,
        Ast::Alternation(_) => false,
        Ast::Group(g) => compiles_to_nothing(&g.ast),
        Ast::Concat(c) => c.asts.iter().all(compiles_to_nothing),
        Ast::Repetition(rep) => match rep.op.kind {
            ast::RepetitionKind::Range(ast::RepetitionRange::Exactly(n)) => n == 0 || compiles_to_nothing(&rep.ast),
            ast::RepetitionKind::Range(ast::RepetitionRange::Bounded(a, b)) if a == b => {
                a == 0 || compiles_to_nothing(&rep.ast)
            }
            _ => false,
        },
    }
}

fn class_is_empty(pattern: &str, span: &Span, state: &FlagState) -> bool {
    let text = format!("{}{}", state.prefix(), &pattern[span.start.offset..span.end.offset]);
    match regex_syntax::ParserBuilder::new().utf8(false).build().parse(&text) {
        Ok(hir) => hir.properties().minimum_len().is_none(),
        Err(_) => false,
    }
}

/// Some constructs that are parse errors with the current parser were parsed
/// differently by the legacy parser (as a counted repetition).
fn legacy_parse_error(pattern: &str, err: &ast::Error) -> Option<String> {
    use regex_syntax::ast::ErrorKind as K;
    let brace = match err.kind() {
        K::SpecialWordBoundaryUnclosed => err.span().start,
        K::SpecialWordOrRepetitionUnexpectedEof => shifted(pattern, err.span().start, 2),
        K::SpecialWordBoundaryUnrecognized => {
            // span covers the contents; the brace is right before.
            let off = pattern[..err.span().start.offset].rfind('{')?;
            let mut p = err.span().start;
            p.column -= pattern[off..err.span().start.offset].chars().count();
            p.offset = off;
            p
        }
        _ => return None,
    };
    let next = shifted(pattern, brace, 1);
    if next.offset >= pattern.len() {
        return Some(render(pattern, &Span::new(brace, next), "unclosed counted repetition"));
    }
    Some(render(pattern, &Span::splat(next), "repetition quantifier expects a valid decimal"))
}

/// Render an error the same way the regex parser renders its diagnostics.
fn render(pattern: &str, span: &Span, msg: &str) -> String {
    let mut line_count = pattern.lines().count();
    if pattern.ends_with('\n') {
        line_count += 1;
    }
    let width = if line_count <= 1 { 0 } else { line_count.to_string().len() };
    let one_line = span.start.line == span.end.line;

    let mut notated = String::new();
    for (i, line) in pattern.lines().enumerate() {
        if width > 0 {
            notated.push_str(&format!("{:>w$}: ", i + 1, w = width));
        } else {
            notated.push_str("    ");
        }
        notated.push_str(line);
        notated.push('\n');
        if one_line && span.start.line == i + 1 {
            let pad = if width == 0 { 4 } else { 2 + width };
            notated.push_str(&" ".repeat(pad));
            notated.push_str(&" ".repeat(span.start.column.saturating_sub(1)));
            let len = span.end.column.saturating_sub(span.start.column);
            notated.push_str(&"^".repeat(std::cmp::max(1, len)));
            notated.push('\n');
        }
    }

    let mut out = String::from("regex parse error:\n");
    if pattern.contains('\n') {
        let divider = "~".repeat(79);
        out.push_str(&divider);
        out.push('\n');
        out.push_str(&notated);
        out.push_str(&divider);
        out.push('\n');
        if !one_line {
            out.push_str(&format!(
                "on line {} (column {}) through line {} (column {})\n",
                span.start.line,
                span.start.column,
                span.end.line,
                span.end.column - 1
            ));
        }
    } else {
        out.push_str(&notated);
    }
    out.push_str("error: ");
    out.push_str(msg);
    out
}
EOF"}

