            }
        }
    }

    fn prefix(&self) -> String {
        let mut s = String::new();
        if self.insensitive {
            s.push('i');
        }
        if self.verbose {
            s.push('x');
        }
        if !self.unicode {
            s.push_str("-u");
        }
        if s.is_empty() {
            s
        } else {
            format!("(?{})", s)
        }
    }
}

