//! Command line parsing.
//!
//! The parser reproduces the conventions (and the exact diagnostics) of the
//! argument parser used by the original tool: grouped short flags, attached
//! values (`-n5`, `-n=5`, `--num=5`), `--` to end option parsing, default
//! values, value validators and "did you mean" suggestions.

use std::io::IsTerminal;

pub const HELP_TEMPLATE: &str = "loop 0.6.1
Rich Jones <miserlou@gmail.com>
UNIX's missing `loop` command

USAGE:
    {bin} [FLAGS] [OPTIONS] [input]...

FLAGS:
    -D, --error-duration    Exit with timeout error code on duration
    -h, --help              Prints help information
    -l, --only-last         Only print the output of the last execution of the command
    -i, --stdin             Read from standard input
        --summary           Provide a summary
