pub fn jaro(a: &str, b: &str) -> f64 {
    if a == b {
        return 1.0;
    }
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() || b.is_empty() || (a.len() == 1 && b.len() == 1) {
        return 0.0;
    }
    let window = std::cmp::max(a.len(), b.len()) / 2 - 1;
    let mut used = vec![false; b.len()];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut last = 0usize;
    for (i, ca) in a.iter().enumerate() {
        let lo = if i > window { i - window } else { 0 };
        let hi = std::cmp::min(b.len() - 1, i + window);
        for j in 0..=hi {
            if j >= lo && *ca == b[j] && !used[j] {
                used[j] = true;
                matches += 1.0;
                if j < last {
                    transpositions += 1.0;
                }
                last = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        return 0.0;
    }
    (1.0 / 3.0) * ((matches / a.len() as f64) + (matches / b.len() as f64) + ((matches - transpositions) / matches))
}

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let base = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let score = base + 0.1 * prefix as f64 * (1.0 - base);
    if score <= 1.0 {
        score
    } else {
        1.0
    }
}

struct Parser {
    bin: String,
    paint: Paint,
    matches: Matches,
}

impl Parser {
    fn full_usage(&self) -> String {
        format!("{} [FLAGS] [OPTIONS] [input]...", self.bin)
    }

    fn usage(&self) -> String {
        let mut names: Vec<&'static str> =
            self.matches.entries.iter().map(|e| e.name).filter(|n| *n != POSITIONAL).collect();
        let body = if names.is_empty() {
            self.full_usage()
        } else {
            names.sort();
            names.dedup();
            let mut s = self.bin.clone();
            for n in names {
                s.push(' ');
                s.push_str(&display_of(n));
            }
            s
        };
        format!("USAGE:\n    {}", body)
    }

    fn unknown(&self, arg: &str, hint: &str) -> Outcome {
        let p = &self.paint;
        let hint = if hint.is_empty() { "\n".to_string() } else { format!("{}\n", hint) };
        Outcome::Failure(format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n{}\n\nFor more information try {}",
            p.error("error:"),
            p.warning(arg),
            hint,
            self.usage(),
            p.good("--help")
        ))
    }

    fn missing_value(&self, name: &str) -> Outcome {
        let p = &self.paint;
        Outcome::Failure(format!(
            "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}",
            p.error("error:"),
            p.warning(&display_of(name)),
            self.usage(),
            p.good("--help")
        ))
    }

    fn repeated(&self, name: &str) -> Outcome {
        let p = &self.paint;
        Outcome::Failure(format!(
            "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
            p.error("error:"),
            p.warning(&display_of(name)),
            self.usage(),
            p.good("--help")
        ))
    }

    fn invalid(&self, name: &str, why: &str) -> Outcome {
        let p = &self.paint;
        Outcome::Failure(format!(
            "{} Invalid value for '{}': {}",
            p.error("error:"),
            p.warning(&display_of(name)),
            why
        ))
    }

    fn help(&self) -> Outcome {
        Outcome::Help(HELP_TEMPLATE.replace("{bin}", &self.bin))
    }

    fn take_option(&mut self, spec: &'static Spec, attached: Option<&str>) -> Pending {
        if let Some(raw) = attached {
            let v = raw.trim_start_matches('=');
            self.matches.entry(spec.name).values.push(v.to_string());
        }
        self.matches.entry(spec.name).occurs += 1;
        if attached.is_none() {
            Pending::Value(spec.name)
        } else {
            Pending::Done
        }
    }

    fn take_flag(&mut self, spec: &'static Spec) -> Result<Pending, Outcome> {
        if spec.name == HELP_NAME {
            return Err(self.help());
        }
        if spec.name == VERSION_NAME {
            return Err(Outcome::Version);
        }
        self.matches.entry(spec.name).occurs += 1;
        Ok(Pending::Flag)
    }

    fn long(&mut self, arg: &str) -> Result<Pending, Outcome> {
        let body = arg.trim_start_matches('-');
        let (name, attached) = match body.find('=') {
            Some(i) if arg.contains('=') => (&body[..i], Some(&body[i..])),
            _ => (body, None),
        };
        if let Some(spec) = OPTIONS.iter().find(|s| s.long == name) {
            return Ok(self.take_option(spec, attached));
        }
        if let Some(spec) = FLAGS.iter().find(|s| s.long == name) {
            return self.take_flag(spec);
        }
        // Not found: try to suggest something close.
        let mut best: Option<(f64, &'static Spec)> = None;
        for spec in FLAGS.iter().chain(OPTIONS.iter()) {
            let score = jaro_winkler(name, spec.long);
            if score > 0.8 && best.map_or(true, |(s, _)| s < score) {
                best = Some((score, spec));
            }
        }
        let mut hint = String::new();
        if let Some((_, spec)) = best {
            hint = format!("\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?", spec.long);
            self.matches.reset(spec.name);
        }
        Err(self.unknown(&format!("--{}", name), &hint))
    }

    fn short(&mut self, arg: &str) -> Result<Pending, Outcome> {
        let body = arg.trim_start_matches('-');
        let mut result = Pending::Nothing;
        for (i, c) in body.char_indices() {
            if let Some(spec) = OPTIONS.iter().find(|s| s.short == Some(c)) {
                let rest = &body[i + c.len_utf8()..];
                let attached = if rest.is_empty() { None } else { Some(rest) };
                return Ok(self.take_option(spec, attached));
            } else if let Some(spec) = FLAGS.iter().find(|s| s.short == Some(c)) {
                result = self.take_flag(spec)?;
            } else {
                return Err(self.unknown(&format!("-{}", c), ""));
            }
        }
        Ok(result)
    }

    fn add_defaults(&mut self) {
        for spec in OPTIONS.iter() {
            if let Some(d) = spec.default {
                let needs = self.matches.get(spec.name).map_or(true, |e| e.values.is_empty());
                if needs {
                    self.matches.entry(spec.name).values.push(d.to_string());
                }
            }
        }
    }

    fn validate(&mut self, pending: Pending) -> Result<(), Outcome> {
        self.add_defaults();
        if let Pending::Value(name) = pending {
            if self.matches.get(name).map_or(true, |e| e.values.is_empty()) {
                return Err(self.missing_value(name));
            }
        }
        for entry in &self.matches.entries {
            if let Some(spec) = find_option(entry.name) {
                if entry.values.is_empty() {
                    return Err(self.missing_value(entry.name));
                }
                if let Some(check) = spec.validator {
                    for v in &entry.values {
                        if let Err(why) = check(v) {
                            return Err(self.invalid(entry.name, &why));
                        }
                    }
                }
                if entry.occurs > 1 {
                    return Err(self.repeated(entry.name));
                }
            } else if find_flag(entry.name).is_some() && entry.occurs > 1 {
                return Err(self.repeated(entry.name));
            }
        }
        Ok(())
    }
}

fn starts_new_arg(arg: &str, pending: Pending) -> bool {
    if pending == Pending::Done {
        return true;
    }
    arg.starts_with('-') && arg.len() != 1
}

pub fn program_name(argv0: Option<&str>) -> String {
    argv0
        .and_then(|a| std::path::Path::new(a).file_name().map(|f| f.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "loop".to_string())
}

pub fn parse(args: &[String]) -> Result<Matches, Outcome> {
    let mut p = Parser {
        bin: program_name(args.first().map(|s| s.as_str())),
        paint: Paint::detect(),
        matches: Matches::default(),
    };
    let mut pending = Pending::Nothing;
    let mut trailing = false;
    for arg in args.iter().skip(1) {
        let fresh = starts_new_arg(arg, pending);
        if !trailing && arg == "--" && fresh {
            trailing = true;
            continue;
        }
        if !trailing {
            if fresh && arg.starts_with("--") {
                pending = p.long(arg)?;
                continue;
            }
            if fresh && arg.starts_with('-') && arg.len() != 1 {
                pending = p.short(arg)?;
                continue;
            }
            if !fresh {
                if let Pending::Value(name) = pending {
                    p.matches.entry(name).values.push(arg.clone());
                    pending = Pending::Done;
                    continue;
                }
            }
        }
        let e = p.matches.entry(POSITIONAL);
        e.values.push(arg.clone());
        e.occurs += 1;
    }
    p.validate(pending)?;
    Ok(p.matches)
}
EOF"}

