            None => 0,
        }
    }
}

fn random_suffix() -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut seed = [0u8; 6];
    let ok = File::open("/dev/urandom").and_then(|mut f| f.read_exact(&mut seed)).is_ok();
    if !ok {
        let t = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
        let mut x = (t as u64) ^ ((std::process::id() as u64) << 32);
        for b in seed.iter_mut() {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            *b = x as u8;
        }
    }
    seed.iter().map(|b| CHARS[(*b as usize) % CHARS.len()] as char).collect()
}

fn open_raw(path: &Path, flags: libc::c_int) -> io::Result<File> {
    let mut bytes = path.as_os_str().as_bytes().to_vec();
    bytes.push(0);
    let fd = unsafe { libc::open(bytes.as_ptr() as *const libc::c_char, flags | libc::O_CLOEXEC, 0o600 as libc::c_uint) };
    if fd < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(unsafe { File::from_raw_fd(fd) })
    }
}

/// Create an anonymous scratch file in the temporary directory.
pub fn scratch_file() -> io::Result<File> {
    let dir = std::env::temp_dir();
    match open_raw(&dir, libc::O_TMPFILE | libc::O_RDWR) {
        Ok(f) => return Ok(f),
        Err(e) => match e.raw_os_error() {
            Some(libc::EOPNOTSUPP) | Some(libc::EISDIR) | Some(libc::ENOENT) => {}
            _ => return Err(e),
        },
    }
    let mut last = None;
    for _ in 0..(1u32 << 31) {
        let path: PathBuf = dir.join(format!(".tmp{}", random_suffix()));
        match open_raw(&path, libc::O_RDWR | libc::O_CREAT | libc::O_EXCL) {
            Ok(f) => {
                let _ = std::fs::remove_file(&path);
                return Ok(f);
            }
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => last = Some(e),
            Err(e) => return Err(e),
        }
        if last.is_some() {
            continue;
        }
    }
    Err(last.unwrap_or_else(|| io::Error::new(io::ErrorKind::AlreadyExists, "too many temporary files exist")))
}

/// Empty the scratch file before running the command again.
pub fn rewind(file: &mut File) {
    let _ = file.set_len(0);
    let _ = file.seek(SeekFrom::Start(0));
}

/// Read everything the command wrote.
pub fn collect(file: &mut File, out: &mut String) -> io::Result<usize> {
    file.seek(SeekFrom::Start(0))?;
    file.read_to_string(out)
}

pub fn print_lines(text: &str) {
    for line in text.lines() {
        println!("{}", line);
    }
}

pub fn print_summary(codes: &[i32]) {
    let failures: Vec<String> = codes.iter().filter(|c| **c != 0).map(|c| c.to_string()).collect();
    println!("Total runs:\t{}", codes.len());
    println!("Successes:\t{}", codes.len() - failures.len());
    if failures.is_empty() {
        println!("Failures:\t0");
    } else {
        println!("Failures:\t{} ({})", failures.len(), failures.join(", "));
    }
}
EOF"}

